CREATE OR REPLACE FUNCTION trip_private.trip_level_trg() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.level := 'full'; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION trip_private.founding_signup_trg() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (SELECT founding_open FROM public.app_settings LIMIT 1) THEN INSERT INTO public.account_consents(user_id,founding_member) VALUES(NEW.id,true) ON CONFLICT(user_id) DO UPDATE SET founding_member=true,updated_at=now(); END IF; RETURN NEW; END $$;
CREATE TRIGGER profiles_founding_signup AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION trip_private.founding_signup_trg();
CREATE OR REPLACE FUNCTION trip_private.accept_legal(p_version text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_created timestamptz; v_open boolean; v_closed timestamptz; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF p_version <> '2026-10-02' THEN RAISE EXCEPTION 'Please review the current terms'; END IF; SELECT created_at INTO v_created FROM auth.users WHERE id=auth.uid(); SELECT founding_open,founding_closed_at INTO v_open,v_closed FROM public.app_settings LIMIT 1; INSERT INTO public.account_consents(user_id,legal_version,accepted_at,founding_member) VALUES(auth.uid(),p_version,now(),coalesce(v_open,false) OR (v_closed IS NOT NULL AND v_created < v_closed)) ON CONFLICT(user_id) DO UPDATE SET legal_version=excluded.legal_version,accepted_at=excluded.accepted_at,updated_at=now(),founding_member=public.account_consents.founding_member OR excluded.founding_member; END $$;
CREATE OR REPLACE FUNCTION trip_private.founding_member(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (p_user=auth.uid() OR EXISTS(SELECT 1 FROM public.trip_members a JOIN public.trip_members b ON a.trip_id=b.trip_id WHERE a.user_id=auth.uid() AND a.status='approved' AND b.user_id=p_user AND b.status='approved')) AND EXISTS(SELECT 1 FROM public.account_consents c WHERE c.user_id=p_user AND c.founding_member) $$;
CREATE OR REPLACE FUNCTION public.founding_member(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT trip_private.founding_member(p_user) $$;
REVOKE ALL ON FUNCTION trip_private.founding_signup_trg(),trip_private.founding_member(uuid),public.founding_member(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION trip_private.founding_member(uuid),public.founding_member(uuid) TO authenticated;